variables.result:
{# Pure transport planning. Inputs are already power/ownership-filtered rows.
   A group is usable only after its COMPLETE actual membership is verified. #}
{% set n = namespace(rows={}, blocked=[], errors=[], candidates=[], used=[], commands=[]) %}
{% for row in rows %}
  {% if row is mapping and row.get('entity') is string and row.get('owner') is string and row.get('topic') is string and row.get('payload') is mapping and row.payload|count > 0 and row.topic.startswith('zigbee2mqtt/') and row.topic.endswith('/set') %}
    {% set e = row.entity %}
    {% if e not in n.blocked %}
      {% if e not in n.rows %}
        {% set n.rows = dict(n.rows, **{e: row}) %}
      {% elif n.rows[e].owner != row.owner or n.rows[e].topic != row.topic or n.rows[e].payload != row.payload %}
        {% set n.blocked = n.blocked + [e] %}
        {% set n.rows = dict(n.rows.items() | rejectattr(0, 'eq', e)) %}
        {% set n.errors = n.errors + [{'entity': e, 'reason': 'conflicting_endpoint_rows'}] %}
      {% endif %}
    {% endif %}
  {% else %}
    {% set n.errors = n.errors + [{'reason': 'invalid_endpoint_row', 'index': loop.index0}] %}
  {% endif %}
{% endfor %}
{% for group in groups %}
  {% if group is mapping and group.get('verified') is sameas true and group.get('topic') is string and group.topic.startswith('zigbee2mqtt/') and group.topic.endswith('/set') and group.get('members') is sequence and group.members is not string and group.members is not mapping and group.members|count > 1 %}
    {% set check = namespace(valid=true) %}
    {% for e in group.members %}{% if e is not string %}{% set check.valid=false %}{% endif %}{% endfor %}
    {% if check.valid and group.members|unique|list|count == group.members|count %}
      {% set n.candidates = n.candidates + [dict(group, size=group.members|count)] %}
    {% endif %}
  {% endif %}
{% endfor %}
{% for group in n.candidates|sort(attribute='topic')|sort(attribute='size', reverse=true) %}
  {% set check = namespace(valid=true, payload=none, owners=[]) %}
  {% for other in n.candidates if other.topic == group.topic %}
    {% if other.members|sort != group.members|sort %}{% set check.valid=false %}{% endif %}
  {% endfor %}
  {% for e in group.members %}
    {% if e in n.used or e not in n.rows %}
      {% set check.valid=false %}
    {% else %}
      {% set row=n.rows[e] %}
      {% if check.payload is none %}{% set check.payload=row.payload %}
      {% elif check.payload != row.payload %}{% set check.valid=false %}{% endif %}
      {% set check.owners=check.owners+[row.owner] %}
    {% endif %}
  {% endfor %}
  {% if check.valid %}
    {% set n.commands=n.commands+[{'topic':group.topic, 'payload':check.payload, 'members':group.members|sort, 'owners':check.owners|unique|sort, 'group':group.get('id',group.topic), 'managed':group.get('managed',false), 'physical_members':group.get('physical_members',[])}] %}
    {% set n.used=n.used+group.members %}
  {% endif %}
{% endfor %}
{% for e, row in n.rows|dictsort if e not in n.used %}
  {% set n.commands=n.commands+[{'topic':row.topic, 'payload':row.payload, 'members':[e], 'owners':[row.owner], 'group':none}] %}
{% endfor %}
{{ {'commands':n.commands, 'rejected':n.errors, 'input_count':rows|count, 'endpoint_count':n.rows|count, 'command_count':n.commands|count} }}

{% set assignments=state_attr('sensor.ls_effects_runtime','assignments') or {} %}
{% set power=state_attr('sensor.ls_overrides','power') or {} %}
{% set actual=state_attr('sensor.ls_effects_runtime','candle_group') or {} %}
{% set n=namespace(lamps={},entities=[],members=[],endpoints={},owners={},remove=[],add=[]) %}
{% for lamp,ends in catalog.members.items() %}
 {% for E in ends %}
  {% for domain,identifier in device_attr(E,'identifiers') or [] %}
   {% if domain=='mqtt' and identifier.startswith('zigbee2mqtt_0x') %}
    {% set ieee=identifier[12:] %}
    {% set n.endpoints=dict(n.endpoints,**{E:{'ieee_address':ieee,'endpoint':1}}) %}
    {% set n.owners=dict(n.owners,**{ieee:lamp}) %}
   {% endif %}
  {% endfor %}
 {% endfor %}
{% endfor %}
{% for lamp,t in assignments.items() if lamp in catalog.members and is_state(lamp,'on') and t.get('on',false) and power.get(t.get('area'),true) %}
 {% if t.get('brightness',{}).get('effect')=='Candle' and t.brightness.get('kind')=='effect'
       and t.get('color',{}).get('effect')=='Candle' and t.color.get('kind')=='effect' %}
  {% set n.lamps=dict(n.lamps,**{lamp:t}) %}
  {% for E in catalog.members[lamp] if is_state(E,'on') and E in n.endpoints %}
   {% set n.entities=n.entities+[E] %}{% set n.members=n.members+[n.endpoints[E]] %}
  {% endfor %}
 {% endif %}
{% endfor %}
{% set wanted=n.members|sort(attribute='ieee_address') %}
{% set members=(actual.get('members',[])|list)|sort(attribute='ieee_address') %}
{% for m in members if m not in wanted %}{% set n.remove=n.remove+[m] %}{% endfor %}
{% for m in wanted if m not in members %}{% set n.add=n.add+[m] %}{% endfor %}
{% set bridge=states.binary_sensor.zigbee2mqtt_bridge_connection_state %}
{% set listener=states.automation.effects_candle_group_state %}
{% set epoch=[as_timestamp(bridge.last_changed if bridge is not none else none,0),as_timestamp(listener.last_changed if listener is not none else none,0)]|max %}
{% set fresh=actual.get('observed_at',0)>=epoch and actual.get('observed_at',0)>0 %}
{% set synchronized=actual.get('exists',false) and fresh and members==wanted %}
{{ {'lamps':n.lamps,'entities':n.entities|unique|sort,'members':wanted,'actual':actual,
    'remove':n.remove,'add':n.add,'owners':n.owners,'fresh':fresh,'synchronized':synchronized,
    'ready':synchronized and wanted|count>0 and not state_attr('sensor.ls_effects_runtime','candle_syncing')
      and is_state('binary_sensor.zigbee2mqtt_bridge_connection_state','on')} }}

variables.plan:
{# One logical input stream per room; each source keeps a bounded snapshot.
   The most recent snapshot includes preceding inputs from the room's other
   remotes, so alternating devices cannot drop or apply a click twice. #}
{% macro latest_remote_key(records,room) -%}
 {% set pick=namespace(key='',stamp=-1) %}
 {% for key,r in records|dictsort if r is mapping and r.get('scope')=='room' and r.get('target')==room and (r.get('kind')=='input' or (r.get('kind')=='channels' and r.get('via')=='remote')) %}
  {% set stamp=as_timestamp(r.get('when'),0) %}
  {% if stamp>=pick.stamp %}{% set pick.key=key %}{% set pick.stamp=stamp %}{% endif %}
 {% endfor %}
 {{- pick.key|to_json -}}
{%- endmacro %}

{% set remote_streams=namespace(by_room={}) %}
{%- set T = (as_datetime(test_now) | as_local) if (test_now is defined and test_now) else now() -%}
{%- set why = reason | default('tick') -%}
{%- set ovr = test_overrides if (test_overrides is defined and test_overrides is mapping) else state_attr('sensor.ls_overrides', 'overrides') -%}
{%- set ovr = ovr if ovr is mapping else {} -%}
{%- set sara = false -%}
{%- set pink = [255, 105, 180] -%}
{%- set rooms = (label_entities('house_schedule') + label_entities('on_off') + (state_attr('sensor.ls_overrides','switch_ranges') or {}).keys()|list + ((label_devices('house_schedule') + label_devices('on_off')) | map('device_entities') | sum(start=[]))) | map('area_id') | select | unique | sort | list -%}
{%- set rooms=([room_only] if room_only in rooms else []) if room_only else rooms -%}
{%- set blocks = ['day', 'cosy', 'night'] -%}
{%- set private = label_areas('private_room') -%}
{%- set midnight = T.replace(hour=0, minute=0, second=0, microsecond=0) -%}
{%- set ns = namespace(sched={}) -%}
{%- for sc in ['house'] + rooms -%}
  {%- set t = namespace(cur=none, cur_ts=0, nxt=none, nxt_ts=0, nxt_f=0, last_fs=0, next_fs=0) -%}
  {%- for off in [-2, -1, 0, 1] -%}
    {%- set eve = midnight + timedelta(days=off) -%}
    {%- set wk = eve.weekday() in [4, 5] -%}
    {%- for b in blocks -%}
      {%- set src = sc if (sc == 'house' or is_state('input_boolean.ls_' ~ sc ~ '_' ~ b ~ '_own_timing', 'on')) else 'house' -%}
      {%- set dayb = b == 'day' -%}
      {%- set wkb = ((eve + timedelta(days=1)).weekday() in [5, 6]) if dayb else wk -%}
      {%- set st = states('input_datetime.ls_' ~ src ~ '_' ~ b ~ ('_weekend' if wkb else '_start')) -%}
      {%- if st | regex_match('^\d\d:\d\d') -%}
        {%- set h = st[0:2] | int -%}
        {%- set i = eve.replace(hour=h, minute=st[3:5] | int) + timedelta(days=(1 if (dayb or h < 12) else 0)) -%}
        {%- set its = as_timestamp(i) -%}
        {%- set f = states('input_number.ls_' ~ src ~ '_' ~ b ~ '_fade') | float(20) * 60 -%}
        {%- if its <= as_timestamp(T) and its > t.cur_ts -%}{%- set t.cur, t.cur_ts = b, its -%}{%- endif -%}
        {%- if its > as_timestamp(T) and (t.nxt is none or its < t.nxt_ts) -%}{%- set t.nxt, t.nxt_ts, t.nxt_f = b, its, f -%}{%- endif -%}
        {%- if its-f>as_timestamp(T) and (t.next_fs==0 or its-f<t.next_fs) -%}{%- set t.next_fs=its-f -%}{%- endif -%}
        {%- if its - f <= as_timestamp(T) and its - f > t.last_fs -%}{%- set t.last_fs = its - f -%}{%- endif -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endfor -%}
  {%- set left = t.nxt_ts - as_timestamp(T) -%}
  {%- set fading = t.nxt is not none and t.nxt_f > 0 and left < t.nxt_f and t.nxt != t.cur -%}
  {%- set ns.sched = dict(ns.sched, **{sc: {'cur': t.cur, 'nxt': t.nxt, 'fading': fading, 'p': ((1 - left / t.nxt_f) if fading else 0), 'edge': (as_timestamp(T) - t.cur_ts) < 90, 'last_fs': t.last_fs, 'next_fs':t.next_fs, 'left': left, 'cur_ts': t.cur_ts}}) -%}
{%- endfor -%}
{%- set dimmables = (label_entities('house_schedule') + (label_devices('house_schedule') | map('device_entities') | sum(start=[]))) | select('match', 'light\.') | unique | list -%}
{%- set plugs = (label_entities('on_off') + (label_devices('on_off') | map('device_entities') | sum(start=[]))) | select('match', '(light|switch)\.') | unique | list -%}
{%- set only = (lights if lights is list else [lights]) if (lights is defined and lights) else [] -%}
{%- set out = namespace(cmds={}, dbg=[], profiles={}) -%}
{%- for L in (dimmables + plugs) if area_id(L)==room and (not only or L in only) -%}
  {%- set is_plug = L in plugs -%}
  {%- set a = area_id(L) -%}
  {%- set room = a if a in rooms else none -%}
  {%- set ts = room or 'house' -%}
{% if ts not in remote_streams.by_room %}{% set remote_streams.by_room=dict(remote_streams.by_room,**{ts:latest_remote_key(ovr,ts)|from_json}) %}{% endif %}
  {%- set lsc = room or 'house' -%}
  {%- set S = ns.sched[ts] -%}
  {%- set st = namespace(fr=S.cur, to=(S.nxt if S.fading else S.cur), p=S.p, moving=S.fading, edge=S.edge, src='schedule') -%}
  {%- set pick = namespace(rec=ovr.get('block:' ~ ts),stamp=as_timestamp(ovr.get('block:' ~ ts,{}).get('when'),0)) -%}
{%- for key,r in ovr|dictsort if r is mapping and r.get('kind') in ['channels','input'] and r.get('value') is mapping -%}
 {%- set matches=(r.get('scope')=='lamp' and r.target==L) or (r.get('scope')=='room' and r.target==ts) or (r.get('scope')=='house' and a not in private) -%}
 {%- set period=r.value.get('period') -%}{%- set stamp=r.value.get('period_updated',as_timestamp(r.get('when'),0))|float -%}
 {%- if matches and (not (r.get('scope')=='room' and (r.get('kind')=='input' or (r.get('kind')=='channels' and r.get('via')=='remote'))) or key==remote_streams.by_room[ts]) and period in blocks and stamp>=pick.stamp and not (is_state('input_boolean.ls_ovr_next_block_on','on') and as_timestamp(r.when,0)<=S.last_fs) -%}{%- set pick.rec={'value':period,'when':r.when} -%}{%- set pick.stamp=stamp -%}{%- endif -%}
{%- endfor -%}{%- set orec=pick.rec -%}
{%- if orec is mapping and is_state('input_boolean.ls_ovr_next_block_on','on') and not S.fading and as_timestamp(orec.when,0)<=S.last_fs -%}{%- set orec=none -%}{%- endif -%}
  {%- set ov = (orec.value | string | lower) if orec is mapping else '' -%}
  {%- set expired=namespace(keys=[],rec=none) -%}
{%- if is_state('input_boolean.ls_ovr_next_block_on','on') -%}
 {%- for key,r in ovr|dictsort if r is mapping -%}
  {%- set applies=(r.kind=='light' and r.target==L) or (r.kind in ['channels','input'] and ((r.get('scope')=='lamp' and r.target==L) or (r.get('scope')=='room' and r.target==ts) or (r.get('scope')=='house' and a not in private))) or (key=='mode:sara' and a not in private) -%}
  {%- if applies and as_timestamp(r.get('when'),0)<=S.last_fs -%}{%- set expired.keys=expired.keys+[key] -%}{%- set expired.rec={'when':r.when,'value':none} -%}{%- endif -%}
 {%- endfor -%}
{%- endif -%}{%- set lrec=expired.rec if S.fading else none -%}
  {%- set effect_record = lrec if (lrec is mapping and lrec.value is mapping and 'effect' in lrec.value and not (S.fading and as_timestamp(lrec.when,0) <= S.last_fs)) else none -%}
  {%- if effect_record is mapping -%}{%- set lrec = none -%}{%- endif -%}
  {%- set srec = ovr.get('mode:sara') if (sara and a not in private) else none -%}
  {%- set lamp_sara = sara and not (S.fading and srec is mapping and as_timestamp(srec.when, 0) <= S.last_fs) -%}
  {%- set fo_p = [1, (60 if why == 'tick' else 3) / ([S.left, 1] | max)] | min -%}
  {%- if lrec is mapping and not (S.fading and as_timestamp(lrec.when, 0) <= S.last_fs) -%}
    {%- set st.src = 'held' -%}
  {%- elif lrec is mapping or (orec is mapping and S.fading and as_timestamp(orec.when, 0) <= S.last_fs) -%}
    {%- set st.fr, st.to, st.p, st.moving, st.edge, st.src = 'lamp', S.nxt, fo_p, true, false, 'fadeout' -%}
  {%- elif ov in blocks -%}
    {%- set st.fr, st.to, st.p, st.moving, st.src = ov, ov, 0, false, 'override' -%}
  {%- elif sara and a not in private and not lamp_sara -%}
    {%- set st.fr, st.to, st.p, st.moving, st.edge, st.src = 'lamp', S.nxt, fo_p, true, false, 'fadeout' -%}
  {%- elif room and has_value('input_datetime.ls_' ~ room ~ '_wake') -%}
    {%- set wts = state_attr('input_datetime.ls_' ~ room ~ '_wake', 'timestamp') | float(0) -%}
    {%- set D = states('input_number.ls_' ~ room ~ '_wake_fade') | float(37.5) * 60 -%}
    {%- set e = as_timestamp(T) - wts -%}
    {%- if 0 <= e < D and S.cur == 'night' and S.cur_ts <= wts -%}
      {%- set st.fr, st.to, st.p, st.moving, st.src = 'night', 'day', e / D, true, 'wake' -%}
    {%- elif D <= e < 86400 and 4 <= (as_datetime(wts) | as_local).hour < 11 and S.cur == 'night' and S.cur_ts <= wts and (not S.fading or S.nxt == 'day') -%}
      {%- set st.fr, st.to, st.p, st.moving, st.edge, st.src = 'day', 'day', 0, false, (e - D) < 90, 'wake' -%}
    {%- endif -%}
  {%- endif -%}
  {%- set send_now = true -%}
  {%- set obj = L.split('.')[1] -%}
  {%- if not is_plug -%}
    {%- set eb = st.to if st.fr == 'lamp' else st.fr -%}
    {%- set esc = room if (room and is_state('input_boolean.ls_' ~ room ~ '_' ~ eb ~ '_own_light','on')) else 'house' -%}
    {%- set lp = states('input_text.ls_lamp_' ~ obj ~ '_' ~ eb)|from_json(default={}) -%}
    {%- set pr = lp if lp.get('own',false) else states('input_text.ls_' ~ esc ~ '_' ~ eb)|from_json(default={}) -%}
    {%- set effect = pr.get('effect','Normal light') if st.src != 'held' else 'Normal light' -%}
    {%- set bright = pr.get('b',255)|int -%}
    {%- if effect_record is mapping -%}
      {%- set effect = effect_record.value.effect -%}
      {%- set bright = effect_record.value.get('brightness',bright)|int -%}
    {%- endif -%}
    {%- if lamp_sara and a not in private -%}{%- set effect='Normal light' -%}{%- endif -%}
    {%- set out.profiles=dict(out.profiles,**{L:{'effect':effect,'brightness':bright,'on':pr.get('on',true),'period':eb,'area':a,'effect_channels':pr.get('effect_channels',['brightness','color']),'send':(why!='tick' or st.moving or st.edge),'ignore_overrides':expired.keys}}) -%}
  {%- endif -%}

  {%- if is_plug -%}
    {%- set blk = st.to if (not st.moving or st.p >= 1) else st.fr -%}
    {%- set lsc = room if (room and is_state('input_boolean.ls_' ~ room ~ '_' ~ blk ~ '_own_light', 'on')) else 'house' -%}
    {%- set lj = states('input_text.ls_lamp_' ~ obj ~ '_' ~ blk) | from_json(default={}) -%}
    {%- set src = ['input_boolean.ls_' ~ lsc ~ '_' ~ blk ~ '_on_off', 'input_boolean.ls_house_' ~ blk ~ '_on_off'] | select('has_value') | first | default(none) -%}
    {%- set want = (lj.get('on', false) | bool) if lj.get('own', false) else (is_state(src, 'on') if src else none) -%}
    {%- if send_now and want is not none and not st.moving -%}
      {%- set svc = 'homeassistant.turn_on' if want else 'homeassistant.turn_off' -%}
